import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DZhUhjDB.js";const p=JSON.parse('{"title":"01 — ¿Qué es la ciberseguridad?","description":"","frontmatter":{"title":"01 — ¿Qué es la ciberseguridad?"},"headers":[],"relativePath":"modules/fundamentos/01-que-es-ciberseguridad.md","filePath":"modules/fundamentos/01-que-es-ciberseguridad.md","lastUpdated":1787330151000}'),i={name:"modules/fundamentos/01-que-es-ciberseguridad.md"};function s(n,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_01-—-¿que-es-la-ciberseguridad" tabindex="-1">01 — ¿Qué es la ciberseguridad? <a class="header-anchor" href="#_01-—-¿que-es-la-ciberseguridad" aria-label="Permalink to &quot;01 — ¿Qué es la ciberseguridad?&quot;">​</a></h1><h2 id="definicion-corta" tabindex="-1">Definición corta <a class="header-anchor" href="#definicion-corta" aria-label="Permalink to &quot;Definición corta&quot;">​</a></h2><p>La <strong>ciberseguridad</strong> es la práctica de proteger sistemas, redes, programas, dispositivos y datos de ataques, daños o accesos no autorizados. Es una disciplina técnica <strong>y</strong> organizativa: la tecnología sola no basta, también importan las personas y los procesos.</p><h2 id="¿por-que-importa" tabindex="-1">¿Por qué importa? <a class="header-anchor" href="#¿por-que-importa" aria-label="Permalink to &quot;¿Por qué importa?&quot;">​</a></h2><p>Cualquier cosa conectada a internet — desde un smartwatch hasta una planta industrial — es un objetivo potencial. Los atacantes buscan:</p><ul><li>💰 Dinero (ransomware, robo de tarjetas, fraude)</li><li>🕵️ Espionaje (estatal o corporativo)</li><li>🎭 Venganza o activismo (hacktivismo)</li><li>🎮 Diversión o fama (script kiddies, CTF)</li><li>🧠 Reto intelectual (los hay éticos y los hay no)</li></ul><p><strong>En el otro lado</strong>, los profesionales de defensa ganan sueldos competitivos, hay mucha demanda global y el trabajo tiene impacto directo en la vida real (un hospital que cae por ransomware es un paciente que no recibe su tratamiento).</p><h2 id="los-grandes-equipos-los-3-teams" tabindex="-1">Los grandes equipos (los 3 &quot;teams&quot;) <a class="header-anchor" href="#los-grandes-equipos-los-3-teams" aria-label="Permalink to &quot;Los grandes equipos (los 3 &quot;teams&quot;)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Equipo</th><th>Mentalidad</th><th>Una frase que los define</th></tr></thead><tbody><tr><td>🔴 <strong>Red Team</strong> (ofensivo)</td><td>&quot;Piensa como el atacante&quot;</td><td>&quot;Si rompo esto, ¿qué tan grave es?&quot;</td></tr><tr><td>🔵 <strong>Blue Team</strong> (defensivo)</td><td>&quot;Piensa como el defensor&quot;</td><td>&quot;¿Cómo detecto esto a tiempo?&quot;</td></tr><tr><td>🟣 <strong>Purple Team</strong> (colaboración)</td><td>&quot;Ambos juntos, mejor&quot;</td><td>&quot;¿Cómo aprendemos los unos de los otros?&quot;</td></tr></tbody></table><blockquote><p>💡 Hay un cuarto equipo creciente: ⚪ <strong>AI Security / ML Security</strong> — protege modelos de IA, mitiga prompt injection, evalúa riesgos de los nuevos LLMs.</p></blockquote><h2 id="roles-profesionales-comunes" tabindex="-1">Roles profesionales comunes <a class="header-anchor" href="#roles-profesionales-comunes" aria-label="Permalink to &quot;Roles profesionales comunes&quot;">​</a></h2><p>Cada equipo tiene roles especializados. Aquí un mapa rápido (este repo tiene una carpeta dedicada a cada uno en <code>01-CIBERSEGURIDAD/</code>):</p><h3 id="🔴-ofensivos-red-team" tabindex="-1">🔴 Ofensivos (Red Team) <a class="header-anchor" href="#🔴-ofensivos-red-team" aria-label="Permalink to &quot;🔴 Ofensivos (Red Team)&quot;">​</a></h3><ul><li><strong>Pentester</strong> — busca vulnerabilidades en sistemas autorizados</li><li><strong>Red Teamer</strong> — simula adversarios reales en ejercicios prolongados</li><li><strong>Bug Bounty Hunter</strong> — trabaja por recompensas públicas</li><li><strong>Exploit Developer</strong> — escribe código que aprovecha vulnerabilidades</li></ul><h3 id="🔵-defensivos-blue-team" tabindex="-1">🔵 Defensivos (Blue Team) <a class="header-anchor" href="#🔵-defensivos-blue-team" aria-label="Permalink to &quot;🔵 Defensivos (Blue Team)&quot;">​</a></h3><ul><li><strong>Analista SOC</strong> — vigila alertas 24/7 en un centro de operaciones</li><li><strong>Threat Hunter</strong> — busca atacantes que ya están dentro</li><li><strong>Incident Responder</strong> — actúa cuando algo se rompe</li><li><strong>Threat Intelligence Analyst</strong> — estudia quién atacaría y cómo</li><li><strong>Malware Analyst</strong> — desarma software malicioso para entenderlo</li></ul><h3 id="🟣-grc-gobernanza-riesgo-cumplimiento" tabindex="-1">🟣 GRC (Gobernanza, Riesgo, Cumplimiento) <a class="header-anchor" href="#🟣-grc-gobernanza-riesgo-cumplimiento" aria-label="Permalink to &quot;🟣 GRC (Gobernanza, Riesgo, Cumplimiento)&quot;">​</a></h3><ul><li><strong>CISO</strong> — el máximo responsable de seguridad en una organización</li><li><strong>Risk Manager</strong> — cuantifica y prioriza riesgos</li><li><strong>Auditor de seguridad</strong> — verifica que se cumplen normas (ISO 27001, NIST, PCI-DSS)</li><li><strong>Data Protection Officer (DPO)</strong> — vela por la privacidad (GDPR, leyes locales)</li><li><strong>GRC Analyst</strong> — une los tres anteriores</li></ul><h3 id="🤖-seguridad-de-ia" tabindex="-1">🤖 Seguridad de IA <a class="header-anchor" href="#🤖-seguridad-de-ia" aria-label="Permalink to &quot;🤖 Seguridad de IA&quot;">​</a></h3><ul><li><strong>AI Red Teamer</strong> — ataca modelos con prompt injection, jailbreaks, etc.</li><li><strong>ML Security Engineer</strong> — protege pipelines de entrenamiento</li><li><strong>AI Governance Officer</strong> — define políticas de uso de IA</li></ul><h3 id="otros-roles-utiles" tabindex="-1">Otros roles útiles <a class="header-anchor" href="#otros-roles-utiles" aria-label="Permalink to &quot;Otros roles útiles&quot;">​</a></h3><ul><li><strong>Arquitecto de seguridad</strong> — diseña cómo se construye un sistema seguro</li><li><strong>Forense digital</strong> — investiga después de un incidente</li><li><strong>DevSecOps</strong> — integra seguridad en el ciclo de desarrollo</li><li><strong>Cryptographer / Criptoanalista</strong> — diseña o rompe criptografía</li></ul><h2 id="las-6-categorias-de-ataque-mas-conocidas-la-cia-triad-ampliada" tabindex="-1">Las 6 &quot;categorías&quot; de ataque más conocidas (la CIA Triad ampliada) <a class="header-anchor" href="#las-6-categorias-de-ataque-mas-conocidas-la-cia-triad-ampliada" aria-label="Permalink to &quot;Las 6 &quot;categorías&quot; de ataque más conocidas (la CIA Triad ampliada)&quot;">​</a></h2><p>Para empezar a hablar el idioma, hay una mnemotecnia clásica:</p><ul><li><strong>C</strong>onfidencialidad — solo quien debe ve la información</li><li><strong>I</strong>ntegridad — la información no se alteró sin permiso</li><li><strong>A</strong>uthentication / Availability — quién eres / que el sistema funcione cuando toca</li></ul><p>Pero en la práctica los atacantes hacen cosas como:</p><ol><li>🦠 <strong>Malware</strong> — virus, gusanos, troyanos, ransomware</li><li>🎣 <strong>Phishing</strong> — ingeniería social por email/mensaje</li><li>🔑 <strong>Robo de credenciales</strong> — bases de datos filtradas, keyloggers</li><li>💣 <strong>Explotación de vulnerabilidades</strong> — bugs en software sin parchear</li><li>🌊 <strong>DDoS</strong> — tumbar un servicio saturándolo</li><li>🕵️ <strong>Insider threat</strong> — el atacante está dentro de la organización</li></ol><h2 id="¿que-necesitas-para-entrar" tabindex="-1">¿Qué necesitas para entrar? <a class="header-anchor" href="#¿que-necesitas-para-entrar" aria-label="Permalink to &quot;¿Qué necesitas para entrar?&quot;">​</a></h2><ul><li><strong>Curiosidad</strong> (no se enseña, se tiene o se desarrolla)</li><li><strong>Ganas de leer documentación</strong> (el 80% del trabajo es leer)</li><li><strong>Paciencia para practicar en labs</strong> (teoría sin práctica es inútil)</li><li><strong>Ética firme</strong> — esto es lo que separa al profesional del criminal</li></ul><p>No necesitas:</p><ul><li>Un título específico (hay caminos autodidactas)</li><li>Ser un genio de las matemáticas (es útil pero no esencial)</li><li>Haber nacido sabiendo (nadie nació sabiendo)</li></ul><h2 id="📌-donde-profundizar-en-este-repo" tabindex="-1">📌 Dónde profundizar en este repo <a class="header-anchor" href="#📌-donde-profundizar-en-este-repo" aria-label="Permalink to &quot;📌 Dónde profundizar en este repo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Carpeta</th></tr></thead><tbody><tr><td>Red Team general</td><td><a href="./../02-pentesting-red-team/"><code>02-pentesting-red-team/</code></a>, <a href="./../01-CIBERSEGURIDAD/02-pentesting-red-team/"><code>01-CIBERSEGURIDAD/02-pentesting-red-team/</code></a></td></tr><tr><td>Blue Team general</td><td><a href="./../03-blue-team-defensa/"><code>03-blue-team-defensa/</code></a>, <a href="./../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/"><code>02-SEGURIDAD-INFORMACION/02-blue-team-defensa/</code></a></td></tr><tr><td>Seguridad de IA</td><td><a href="./../03-IA-AGENTES-HERRAMIENTAS/"><code>03-IA-AGENTES-HERRAMIENTAS/</code></a></td></tr><tr><td>Roles profesionales</td><td><a href="./../01-CIBERSEGURIDAD/"><code>01-CIBERSEGURIDAD/</code></a> (37 subcarpetas)</td></tr><tr><td>Labs para practicar</td><td><a href="./../04-LABORATORIOS/"><code>04-LABORATORIOS/</code></a></td></tr><tr><td>Certificaciones recomendadas</td><td><a href="./../05-RECURSOS/certificaciones/"><code>05-RECURSOS/certificaciones/</code></a></td></tr></tbody></table><h2 id="✏️-ejercicio-para-ti" tabindex="-1">✏️ Ejercicio para ti <a class="header-anchor" href="#✏️-ejercicio-para-ti" aria-label="Permalink to &quot;✏️ Ejercicio para ti&quot;">​</a></h2><ol><li>Escoge <strong>uno</strong> de los equipos (Red / Blue / Purple / AI).</li><li>Escribe en tu libreta: ¿qué hace una persona en ese equipo un lunes cualquiera?</li><li>Busca en <a href="./../01-CIBERSEGURIDAD/"><code>01-CIBERSEGURIDAD/</code></a> una subcarpeta que se llame como un rol de ese equipo.</li><li>Léela y compara con lo que tú escribiste.</li></ol><blockquote><p>⏭️ <strong>Siguiente:</strong> <a href="./02-glosario"><code>02-glosario.md</code></a> — los términos que verás en todos los archivos de este repo.</p></blockquote>',36)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
